"""Read-only access to the source workbook, for use as a test oracle.

The workbook is opened read-only and never written. It is the reference the ported
equations are checked against, so the tests compare against numbers this project
did not produce.

Two oracles are available and the tests use both:

* the cached cell values in the workbook's 'Hybrid Calculator' sheet, which cover
  one worked example in depth, and
* ``data/synthetic_dataset.csv``, whose 2000 rows were generated by these same
  equations and therefore check the port across a wide range of inputs.

The second is the stronger check. It was confirmed by hand that row 1 reproduces
from the cell formulas to within one part in 10^6, so agreeing with it is evidence
the port is faithful rather than evidence of a circular test.
"""

from __future__ import annotations

from functools import lru_cache
from pathlib import Path

__all__ = [
    "WORKBOOK_PATH",
    "DATASET_PATH",
    "WORKED_EXAMPLE_INPUTS",
    "WORKED_EXAMPLE_RESULTS",
    "read_calculator_cells",
    "read_dataset",
]

_REPO_ROOT = Path(__file__).resolve().parent.parent
WORKBOOK_PATH = (
    _REPO_ROOT
    / "data"
    / "reference"
    / "Hybrid_Physics_ML_Impulse_Generator_Optimiser.xlsx"
)
DATASET_PATH = _REPO_ROOT / "data" / "synthetic_dataset.csv"

#: Inputs of the workbook's single worked example, cells B5-B15.
WORKED_EXAMPLE_INPUTS: dict[str, float | str] = {
    "max_system_voltage_kv": 400.0,  # B5, referenced by no formula
    "impulse_type": "Lightning",  # B6
    "test_voltage_kv": 1425.0,  # B7
    "load_c_pf": 850.0,  # B8
    "divider_c_pf": 500.0,  # B9
    "stray_c_pf": 150.0,  # B10
    "stray_l_uh": 18.5,  # B11
    "efficiency": 0.82,  # B12
    "max_stages": 15.0,  # B13
    "max_stage_voltage_kv": 200.0,  # B14
    "stage_capacitance_uf": 3.0,  # B15
}

#: Cached results of that example, transcribed from the workbook's own cells.
#: Kept as literals so the test suite still has an oracle if the workbook file is
#: not present, and so that a change in the file is detected rather than absorbed.
WORKED_EXAMPLE_RESULTS: dict[str, float] = {
    "E5": 1.2,  # target front time, us
    "E6": 50.0,  # target tail time, us
    "E7": 1500.0,  # total load capacitance, pF
    "E8": 9.0,  # required stages
    "E9": 193.08943089430895,  # charging voltage per stage, kV
    "E10": 0.9654471544715447,  # stage utilisation
    "E11": 0.3333333333333333,  # generator capacitance, uF
    "E12": 445.69925298597315,  # theoretical total front R, ohm
    "E13": 49.52213922066368,  # theoretical front R per stage, ohm
    "E14": 50.0,  # selected front R per stage, ohm
    "E15": 215.48055395740815,  # theoretical total tail R, ohm
    "E16": 23.94228377304535,  # theoretical tail R per stage, ohm
    "E17": 25.0,  # selected tail R per stage, ohm
    "E18": 1.2100299583068181,  # physics front time, us
    "E19": 52.20888749999999,  # physics tail time, us
    "E20": 1425.0,  # physics crest, kV (= B7)
}


@lru_cache(maxsize=1)
def read_calculator_cells() -> dict[str, float | str] | None:
    """Cached values of the 'Hybrid Calculator' sheet, or ``None`` if unavailable.

    Opened read-only with ``data_only=True`` so the values Excel last computed are
    returned rather than the formula strings. The file is never saved.
    """
    if not WORKBOOK_PATH.exists():
        return None
    import openpyxl

    workbook = openpyxl.load_workbook(
        WORKBOOK_PATH, data_only=True, read_only=True
    )
    try:
        sheet = workbook["Hybrid Calculator"]
        return {
            cell.coordinate: cell.value
            for row in sheet.iter_rows()
            for cell in row
            if cell.value is not None
        }
    finally:
        workbook.close()


@lru_cache(maxsize=1)
def read_dataset():
    """The synthetic dataset as a DataFrame, or ``None`` if the file is absent."""
    if not DATASET_PATH.exists():
        return None
    import pandas as pd

    return pd.read_csv(DATASET_PATH)
